mapper.select:
SELECT id, user_id, type, ref_id, message, is_read, created_at
  FROM notifications
 WHERE user_id = #{userId}
 ORDER BY created_at DESC, id DESC
 LIMIT #{limit}

mapper.update:
UPDATE notifications
   SET is_read = TRUE
 WHERE id = #{id}
   AND user_id = #{userId}

mapper.delete:
DELETE FROM notifications
 WHERE id = #{id}
   AND user_id = #{userId}
